%[text] Zadanie 2
%[text] $f(x) = e^{-x}, \\qquad g(x) = \\frac{1}{1 + x}$
x = (0:0.25:3)';
F = exp(-x);
G = 1./(1+x);
Difference = G-F;
T = table( x, F, G, Difference, 'VariableNames', {'x', 'F', 'G', 'Difference'}) %[output:0fd4ca1f]

[maxDiff, idx] = max(T.Difference);
xAtMaxDiff = T.x(idx);
fprintf('Największa różnica G - F wynosi %.4f dla x = %.2f\n', maxDiff, xAtMaxDiff); %[output:170566a0]

hold on %[output:9c5cb408]
plot(x, F,'-o', 'LineWidth', 1.5) %[output:9c5cb408]
plot(x, G, '-s', 'LineWidth', 1.5) %[output:9c5cb408]
hold off  %[output:9c5cb408]
grid on %[output:9c5cb408]
xlabel('x'), ylabel('Wartość funkcji') %[output:9c5cb408]
title('Porównanie f(x) = e^{-x} oraz g(x) = 1/(1+x)') %[output:9c5cb408]
legend('f(x) = e^{-x}', 'g(x) = 1/(1+x)', 'Location', 'best') %[output:9c5cb408]
%[text] Dla x = 0 obie funkcje są równe (f(0) = g(0) = 1). Dla x \> 0 większe wartości przyjmuje funkcja g(x) = 1/(1+x) (różnica g(x) - f(x) jest dodatnia na całym przedziale (0, 3\]), ponieważ e^{-x} maleje szybciej niż 1/(1+x). Największa różnica występuje dla x = 1.00 i wynosi około 0.1321.

